+      silenceThresholdMs: this.voiceConfig.silenceThresholdMs ?? 500,
+      vadThreshold: this.voiceConfig.vadThreshold ?? DEFAULT_LOCAL_VAD_THRESHOLD,
+      minTurnDurationMs: this.voiceConfig.minTurnDurationMs ?? 100,
